class Solution {
    public boolean isPalindrome(String string) {
        int i = 0;
        int j = string.length() - 1;
        while (i < j) {
            if (string.charAt(i)!= string.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    public String makePalindrome(String string) {
        if (string.isEmpty()) {
            return "";
        }

        int beginningOfSuffix = 0;

        while (!isPalindrome(string.substring(beginningOfSuffix))) {
            beginningOfSuffix++;
        }

        String suffix = string.substring(beginningOfSuffix);
        String prefix = string.substring(0, beginningOfSuffix);
        StringBuilder reversedPrefix = new StringBuilder(prefix).reverse();
        return string + reversedPrefix.toString();
    }
}
